<script setup>
import { sampleName } from '../utils/sampleName.js'
import {computed,ref,watch,useId} from 'vue'
import {Download} from '@lucide/vue'
import {getLibraryQc} from '../api/client.js'
import {exportTsv,downloadBlob} from '../utils/data.js'
import Pagination from './Pagination.vue'
const props=defineProps({profiles:{type:Array,default:()=>[]},detail:Boolean})
const data=ref(null),loading=ref(true),error=ref(''),page=ref(1),pageSize=ref(10),selected=ref(''),uid=useId()
const metrics=[['raw_read_records','Raw read records'],['clean_read_records','Clean read records'],['retained_alignment_records','Retained alignments'],['mapq20_retention_percent','MAPQ20 retention'],['unique_alignment_percent','Unique alignment'],['rrna_percent','rRNA'],['clean_gc_percent','Clean GC'],['clean_base_quality','Base quality']]
async function load(){loading.value=true;error.value='';try{const result=await getLibraryQc();if(result.version!==1||!Array.isArray(result.profiles))throw Error('Unsupported QC data version');const ids=new Set(result.profiles.map(p=>p.profile_id));if(props.profiles.some(p=>!ids.has(p.id)))throw Error('Library QC and profile catalog do not match');data.value=result}catch(e){error.value=e.message}finally{loading.value=false}}
load()
const rows=computed(()=>{const map=new Map(data.value?.profiles.map(p=>[p.profile_id,p])||[]);return props.profiles.flatMap(p=>{const runs=map.get(p.id)?.runs||[];return (runs.length?runs:[{run:null,metrics:{},fastqc:{}}]).map(r=>({...r,profile:p,key:p.id+':'+(r.run||'unmapped')}))})})
const shown=computed(()=>rows.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
const active=computed(()=>rows.value.find(r=>r.key===selected.value))
watch(()=>props.profiles.map(p=>p.id).join(','),()=>{page.value=1;selected.value=''})
watch(pageSize,()=>{page.value=1})
function format(r,key){const m=r.metrics[key];if(!m)return 'Not available';if(typeof m.value==='number')return key.endsWith('_percent')?m.value.toFixed(2)+'%':m.value.toLocaleString('en-US');return m.value.toUpperCase()}
function sourceLabel(m){return m?[m.unit,...(Array.isArray(m.source)?m.source:[m.source])].join('\n'):'No report available for this metric'}
const selectedSources=computed(()=>active.value?[...new Set(Object.values(active.value.metrics).flatMap(m=>Array.isArray(m.source)?m.source:[m.source]))]:[])
function download(){const cols=[{key:'profile',label:'profile_id'},{key:'sample_name',label:'sample_name'},{key:'assay',label:'assay'},{key:'cell',label:'cell'},{key:'run',label:'run'},...metrics.map(([key])=>({key,label:key})),{key:'alignment_unit',label:'retained_alignment_unit'}];exportTsv('NascentAtlas_library_QC.tsv',cols,rows.value.map(r=>({profile:r.profile.id,sample_name:sampleName(r.profile),assay:r.profile.assay,cell:r.profile.cell,run:r.run,alignment_unit:r.metrics.retained_alignment_records?.unit,...Object.fromEntries(metrics.map(([k])=>[k,r.metrics[k]?.value??'']))})))}
function downloadSources(){const used=new Set(rows.value.flatMap(r=>Object.values(r.metrics).flatMap(m=>Array.isArray(m.source)?m.source:[m.source])));downloadBlob('NascentAtlas_library_QC_provenance.json',JSON.stringify({version:data.value.version,catalog_sha256:data.value.catalog_sha256,method:data.value.method,sources:Object.fromEntries([...used].map(s=>[s,data.value.sources[s]])),profiles:rows.value.map(r=>({profile_id:r.profile.id,sample_name:sampleName(r.profile),run:r.run,metrics:r.metrics,fastqc:r.fastqc}))},null,2))}
</script>
<template>
 <section class="panel library-qc-card" aria-label="Library QC">
  <div class="panel-head"><div><h2>Library QC</h2><p>Report-derived metrics for each sequencing run.</p></div><button class="button secondary" type="button" :disabled="!data||!rows.length" @click="download"><Download :size="15"/>Download QC</button></div>
  <p v-if="loading" class="qc-message" role="status">Loading library QC…</p>
  <div v-else-if="error" class="qc-message" role="alert"><p>Unable to load library QC: {{error}}</p><button type="button" class="button secondary" @click="load">Retry library QC</button></div>
  <template v-else>
   <div class="qc-context">{{profiles.length}} profile{{profiles.length===1?'':'s'}} · {{rows.filter(r=>r.run).length}} sequencing runs<span>Read records include reported mates; alignment units are shown separately.</span></div>
   <div v-if="rows.length" class="table-scroll qc-scroll" tabindex="0" role="region" aria-label="Library QC table, scroll horizontally for all metrics"><table><thead><tr><th scope="col">Profile / run</th><th v-if="!detail" scope="col">Assay / cell</th><th v-for="[key,label] in metrics" :key="key" scope="col">{{label}}<small v-if="key==='clean_base_quality'">FastQC module</small></th><th scope="col">Sources</th></tr></thead><tbody><tr v-for="r in shown" :key="r.key" :data-profile="r.profile.id" :data-run="r.run"><td><RouterLink :to="`/samples/${r.profile.id}`" class="table-link">{{ sampleName(r.profile) }}</RouterLink><a v-if="r.run" :href="`https://www.ncbi.nlm.nih.gov/sra/${r.run}`" target="_blank" rel="noopener noreferrer" class="qc-run">{{r.run}} ↗</a><span v-else class="qc-unavailable">Run not mapped</span></td><td v-if="!detail">{{r.profile.assay}}<small>{{r.profile.cell}}</small></td><td v-for="[key] in metrics" :key="key" :title="sourceLabel(r.metrics[key])" :data-metric="key" :class="{'qc-unavailable':!r.metrics[key]}"><span :class="key==='clean_base_quality'&&r.metrics[key]?['qc-status','qc-'+r.metrics[key].value]:[]">{{format(r,key)}}</span><small v-if="key==='retained_alignment_records'&&r.metrics[key]">{{r.metrics[key].unit}}</small></td><td><button type="button" class="qc-source-button" :disabled="!r.run" :aria-expanded="selected===r.key" :aria-controls="`qc-sources-${uid}`" @click="selected=selected===r.key?'':r.key">View sources</button></td></tr></tbody></table></div>
   <p v-else class="qc-message">No profiles match the current filters.</p>
   <div v-if="rows.length" class="qc-pagination"><label>Runs per page<select v-model.number="pageSize" aria-label="QC runs per page"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label><Pagination v-model="page" :total="rows.length" :size="pageSize"/></div>
   <section v-if="active" :id="`qc-sources-${uid}`" class="qc-source-details" aria-label="Selected run QC sources"><h3>{{ sampleName(active.profile) }} · {{active.run}}</h3><dl><template v-for="[key,label] in metrics" :key="key"><dt>{{label}}</dt><dd>{{format(active,key)}}<small>{{sourceLabel(active.metrics[key])}}</small></dd></template></dl><details><summary>Report checksums</summary><p v-for="s in selectedSources" :key="s"><strong>{{s}}</strong><code>SHA256 {{data.sources[s]?.sha256}}</code></p></details><details><summary>Individual FastQC files</summary><div v-for="stage in ['raw','clean']" :key="stage"><h4>{{stage==='raw'?'Raw':'Clean'}}</h4><p v-for="f in active.fastqc[stage]||[]" :key="f.filename">{{f.filename}} · {{f.mate}} · {{f.read_records?.toLocaleString('en-US')}} read records · GC {{f.gc_percent}}% · Per-base quality {{f.base_quality}}</p></div></details></section>
   <details class="qc-methods"><summary>How to read these QC metrics</summary><p>Raw and clean counts sum FASTQ read records across reported mates. Paired-end read counts therefore count both ends. Clean GC is weighted by FastQC read counts; base quality is the worst reported mate's per-base quality module, rather than an overall library verdict.</p><p>MAPQ20 retention uses input BAM records as its denominator and is different from the overall mapping rate. GRO-seq and available PRO-seq retained counts are MAPQ ≥20 read records; mNET-seq counts are unique proper pairs or R2-only reads as labelled. Missing reports are shown as Not available.</p><p>Each metric retains its report source. Where available, v2 clean FastQC files take precedence for the same run and mate.</p><button type="button" class="button secondary" @click="downloadSources">Download QC provenance</button></details>
  </template>
 </section>
</template>
<style scoped>
.library-qc-card{min-width:0;overflow:hidden}.library-qc-card .panel-head{gap:16px;flex-wrap:wrap}.library-qc-card .panel-head .button{font-size:12px}.qc-message{padding:20px 24px;font-size:13px;color:#64748b}.qc-context{display:flex;gap:8px 20px;flex-wrap:wrap;padding:0 24px 18px;font-size:12px;color:#345776;font-variant-numeric:tabular-nums}.qc-context>span{color:#64748b}.qc-scroll{scrollbar-width:thin}.qc-scroll table{width:100%;min-width:1520px;font-size:12px}.qc-scroll th{background:#3e77ab;color:white;font-weight:600;padding:13px 14px;white-space:nowrap}.qc-scroll td{padding:17px 14px;font-variant-numeric:tabular-nums;vertical-align:middle;white-space:nowrap;border-bottom:0;color:#345776}.qc-scroll tr:nth-child(odd){background:#f5f7f9}.qc-scroll tr:nth-child(even){background:white}.qc-scroll small{display:block;font-size:10px;color:#64748b;margin-top:5px}.qc-scroll th small{color:#e7eff7}.qc-scroll .table-link{font-size:12px;color:#3e77ab}.qc-scroll td:first-child .table-link{display:block;min-width:210px;max-width:300px;white-space:normal;overflow-wrap:anywhere}.qc-run{display:block;font-size:11px;color:#64748b;margin-top:5px}.qc-scroll .qc-unavailable,.qc-unavailable{color:#8392a4;font-size:11px}.qc-status{font-size:11px;font-weight:600;padding:4px 7px;border-radius:4px}.qc-pass{background:#e9f4ee;color:#26734d}.qc-warn{background:#fff4df;color:#946922}.qc-fail{background:#fceeee;color:#a13f49}.qc-source-button{background:white;border:1px solid #d5dfeb;border-radius:4px;padding:7px 9px;color:#345776;font:inherit;font-size:11px}.qc-source-button[aria-expanded=true]{background:#edf4fb}.qc-pagination{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:16px;border-top:1px solid #e4ebf2}.qc-pagination>label{display:flex;align-items:center;gap:8px;font-size:11px;color:#64748b}.qc-pagination select{background:white;border:1px solid #d5dfeb;border-radius:4px;font:inherit;color:#345776;padding:5px 8px}.qc-pagination :deep(.pagination){padding:0;border:0;flex:1}.qc-methods{padding:16px 24px;border-top:1px solid #e4ebf2;font-size:12px;color:#64748b;line-height:1.8}.qc-methods summary,.qc-source-details summary{cursor:pointer;color:#345776;font-weight:500}.qc-methods p{margin:12px 0}.qc-methods button{font-size:12px;margin-top:8px}.qc-source-details{padding:20px 24px;background:#f8fafc;border-top:1px solid #e4ebf2;overflow-wrap:anywhere;font-size:12px;color:#345776}.qc-source-details h3{margin:0 0 16px;font-size:15px}.qc-source-details dl{display:grid;grid-template-columns:165px minmax(0,1fr);gap:12px;margin:0 0 18px}.qc-source-details dd{margin:0}.qc-source-details dd small{display:block;white-space:pre-line;font-size:11px;color:#64748b;margin-top:4px}.qc-source-details details{margin-top:14px}.qc-source-details code{display:block;overflow-wrap:anywhere;white-space:normal;font-size:10px;color:#64748b}.qc-source-details h4{margin:12px 0 4px}.library-qc-card :focus-visible{outline:2px solid #7299bd;outline-offset:3px}
@media(max-width:760px){.qc-context{padding:0 20px 16px}.qc-pagination :deep(.pagination){flex-basis:100%}.qc-source-details{padding:18px}.qc-source-details dl{grid-template-columns:1fr;gap:5px}.qc-source-details dd{margin-bottom:10px}.qc-methods{padding:16px 20px}}
</style>
